package com.asmj.marketplace.security; import com.asmj.marketplace.user.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; @Service @RequiredArgsConstructor public class CustomUserDetailsService implements UserDetailsService {private final UserRepository repo; public UserDetails loadUserByUsername(String email)throws UsernameNotFoundException{return repo.findByEmailIgnoreCase(email).map(u->new org.springframework.security.core.userdetails.User(u.getEmail(),u.getPassword(),u.getRoles().stream().map(r->new SimpleGrantedAuthority("ROLE_"+r)).toList())).orElseThrow(()->new UsernameNotFoundException("User not found"));}}
